export function localize(root) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (
      node.parentElement?.closest(
        "textarea,script,style,canvas,.entry-name,.winner h3,#wheel-title,#last-pick",
      )
    )
      continue;
    const key = node.textContent.trim();
    if (messages.en[key] && messages[locale]?.[key])
      node.textContent = node.textContent.replace(key, messages[locale][key]);
  }
  for (const el of root.querySelectorAll("[aria-label],[placeholder]"))
    for (const attr of ["aria-label", "placeholder"]) {
      const key = el.getAttribute(attr);
      if (key && messages[locale]?.[key])
        el.setAttribute(attr, messages[locale][key]);
    }
}

